
// Release v3: remove stale PWA caches from earlier beta builds. Mixed cached HTML/CSS caused visual corruption on GitHub Pages.
(function cleanupLegacyCaches(){
  try{ if('serviceWorker' in navigator){ navigator.serviceWorker.getRegistrations().then(rs=>rs.forEach(r=>r.unregister())).catch(()=>{}); }
  }catch(e){}
  try{ if('caches' in window){ caches.keys().then(keys=>Promise.all(keys.filter(k=>/^castiraq-/i.test(k)).map(k=>caches.delete(k)))).catch(()=>{}); }
  }catch(e){}
})();

const DB=window.CastDB;DB.init();const page=document.body.dataset.page;const $=(q,r=document)=>r.querySelector(q),$$=(q,r=document)=>[...r.querySelectorAll(q)];
function toast(msg){let t=$('#toast');if(!t){t=document.createElement('div');t.className='toast';t.id='toast';document.body.appendChild(t)}t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1800)}
function money(n){return Number(n||0).toLocaleString('en-US')+' د.ع'}

function verifiedBadge(label='حساب موثق',extra=''){return `<span class="ig-verified ${extra}" role="img" aria-label="${label}" title="${label}"><svg viewBox="0 0 24 24" aria-hidden="true"><path class="ig-verified-shape" d="M23 12l-2.44-2.78.34-3.68-3.61-.82L15.4 1.54 12 3 8.6 1.54 6.71 4.72l-3.61.81.34 3.68L1 12l2.44 2.78-.34 3.69 3.61.82 1.89 3.18L12 21l3.4 1.46 1.89-3.18 3.61-.82-.34-3.68L23 12z"/><path class="ig-verified-check" d="M10.09 16.72 6.29 12.91l1.48-1.48 2.32 2.34 6.14-6.14 1.48 1.48-7.62 7.61z"/></svg></span>`}
function qs(name){return new URLSearchParams(location.search).get(name)}
function companyById(id,s=DB.state()){return s.companies.find(c=>c.id===id)}
function talentByUser(id,s=DB.state()){return s.talents.find(t=>t.userId===id)}
function companyByUser(id,s=DB.state()){return s.companies.find(c=>c.userId===id)}
function roleOf(project,roleId){return project?.roles?.find(r=>r.id===roleId)}
function statusLabel(st){return({to_review:'بانتظار المراجعة',reviewed:'تمت المراجعة',selected:'Selected',under_consideration:'Under consideration',self_tape_requested:'Self‑Tape',callback:'Callback',on_avail:'On avail',on_hold:'On hold',backup:'Backup',booked:'Booked',released:'Released',rejected:'Not selected'})[st]||st}
function statusClass(st){return['booked','selected'].includes(st)?'green':['rejected','released'].includes(st)?'red':['under_consideration','self_tape_requested','callback'].includes(st)?'blue':'yellow'}
function cardTalent(t){const img=t.image?`<img src="${t.image}" alt="${t.name}" loading="lazy">`:`<div class="fallback">${t.gender==='female'?'👩🏻':'👨🏻'}</div>`;return `<article class="talent-card"><a href="talent.html?id=${t.id}"><div class="talent-photo">${img}</div></a><div class="talent-body"><div class="talent-top"><b class="verified-name">${t.name}${t.verified?verifiedBadge('حساب موثق','compact'):''}</b></div><div class="meta">${t.type} • ${t.age} سنة • ${t.city}</div><div class="meta">Playing age: ${t.playingAge||'-'} • ${t.available?'متاح':'غير متاح'}</div><div class="tags">${(t.skills||[]).slice(0,3).map(x=>`<span class="tag">${x}</span>`).join('')}</div><div class="card-actions"><a class="btn secondary sm" href="talent.html?id=${t.id}">البروفايل</a><button class="btn primary sm" data-quick-shortlist="${t.id}">+ Shortlist</button></div></div></article>`}
function cardCasting(p){const s=DB.state(),c=companyById(p.companyId,s),roles=p.roles?.length||0;return `<article class="casting-item"><div><b>${p.title}</b><br><small><span class="verified-name">${c?.name||'شركة'}${c?.verified?verifiedBadge('شركة موثقة','compact'):''}</span></small></div><div><small>المدينة / التصوير</small><br>${p.city} • ${p.shootDate}</div><div><small>الأدوار / الأجر</small><br>${roles} دور • ${p.budget}</div><a class="btn primary sm" href="casting.html?id=${p.id}">التفاصيل</a></article>`}
function roleLabel(role){return({admin:'إدارة المنصة',company:'حساب شركة',talent:'حساب موهبة',photographer:'حساب مصور'})[role]||'حساب'}
function pageNavKey(){return page==='talent'?'explore':page==='casting'?'castings':page==='company'?'companies':page}
