function authPage(){const loginTab=$('#loginTab'),signupTab=$('#signupTab'),login=$('#loginPanel'),signup=$('#signupPanel');function mode(m){const l=m==='login';login.classList.toggle('hidden',!l);signup.classList.toggle('hidden',l);loginTab.classList.toggle('active',l);signupTab.classList.toggle('active',!l)}loginTab.onclick=()=>{location.hash='login';mode('login')};signupTab.onclick=()=>{location.hash='signup';mode('signup')};mode(location.hash==='#signup'?'signup':'login');addEventListener('hashchange',()=>mode(location.hash==='#signup'?'signup':'login'));$$('[data-demo]').forEach(b=>b.onclick=()=>{$('#loginEmail').value=b.dataset.demo;$('#loginPassword').value='123456'});$('#loginForm').onsubmit=e=>{e.preventDefault();const u=DB.login($('#loginEmail').value,$('#loginPassword').value);if(!u)return toast('الإيميل أو كلمة المرور غير صحيحة');location.href='dashboard.html'};const cities=['بغداد','أربيل','البصرة','النجف','كربلاء','السليمانية','الموصل'];$('#signupCity').innerHTML=cities.map(x=>`<option>${x}</option>`).join('');let role='talent';function setRole(r){role=r;$('#signupRole').value=r;$$('[data-role]').forEach(x=>x.classList.toggle('active',x.dataset.role===r));$('#signupNameLabel').childNodes[0].nodeValue=r==='company'?'اسم الشركة ':r==='photographer'?'اسم المصور ':'الاسم الكامل ';$('#signupExtraLabel').childNodes[0].nodeValue=r==='company'?'نوع الجهة ':r==='photographer'?'التخصص الرئيسي ':'الفئة ';$('#signupExtra').innerHTML=(r==='company'?['Production House','Agency','Director','Brand']:r==='photographer'?['Commercial','Fashion','Beauty','Product','Events','Real Estate','Videography','Photography']:['مودل','ممثل','UGC','كومبارس']).map(x=>`<option>${x}</option>`).join('')}$$('[data-role]').forEach(x=>x.onclick=()=>setRole(x.dataset.role));setRole('talent');const photoChoice=$('[data-role="photographer"]');if(photoChoice&&DB.featureEnabled&&!DB.featureEnabled('photographer_accounts',null))photoChoice.hidden=true;$('#signupNext').onclick=()=>{$('#signupStep1').classList.add('hidden');$('#signupForm').classList.remove('hidden');$('#signupStepLabel').textContent='2'};$('#signupBack').onclick=()=>{$('#signupForm').classList.add('hidden');$('#signupStep1').classList.remove('hidden');$('#signupStepLabel').textContent='1'};$('#signupForm').onsubmit=e=>{e.preventDefault();try{DB.register({role:$('#signupRole').value,name:$('#signupName').value.trim(),email:$('#signupEmail').value.trim(),city:$('#signupCity').value,password:$('#signupPassword').value,extra:$('#signupExtra').value});location.href='dashboard.html'}catch(err){toast(err.message==='EMAIL_EXISTS'?'الإيميل مسجل مسبقاً':'تعذر إنشاء الحساب')}}}

