function metric(l,v,s){return `<div class="metric"><span>${l}</span><b>${v}</b><small>${s}</small></div>`}function panel(title,body,action=''){return `<section class="panel"><div class="panel-head"><h3>${title}</h3>${action}</div>${body}</section>`}function bars(rows){return rows.map(([l,v])=>`<div class="bar-row"><div class="bar-label"><span>${l}</span><b>${v}%</b></div><div class="bar"><span style="width:${v}%"></span></div></div>`).join('')}
function dashboardPage(){const u=DB.currentUser();if(!u)return location.href='auth.html#login';document.body.classList.remove('role-talent','role-company','role-photographer','role-admin');document.body.classList.add('role-'+u.role);$('#sidebarName').textContent=u.name;$('#sidebarRole').textContent=u.role;$('#sidebarAvatar').textContent=u.name[0]||'U';$('#logoutBtn').onclick=()=>{DB.logout();location.href='index.html'};function renderNav(){const navItems=dashNav[u.role].filter(([id])=>u.role!=='photographer'||(id!=='storyboard'||!DB.featureEnabled||DB.featureEnabled('storyboard',u))&&(id!=='messages'||!DB.featureEnabled||DB.featureEnabled('chat',u)));$('#dashboardNav').innerHTML=navItems.map(([id,ic,l])=>`<a class="side-link ${id===dashSection?'active':''}" data-dash="${id}">${ic} ${l}</a>`).join('');$$('[data-dash]').forEach(a=>a.onclick=()=>{dashSection=a.dataset.dash;renderNav();render()})}function render(){const labels={overview:'نظرة عامة',profile:'بروفايلي',portfolio:'محتواي',opportunities:'الفرص',applications:'طلباتي',selftapes:'Self‑Tapes',messages:'الرسائل',analytics:'الإحصائيات',projects:'المشاريع',submissions:'المتقدمون',search:'بحث المواهب',shortlists:'Shortlists',schedule:'الجدولة',users:'المستخدمون',verification:'طلبات التوثيق',castings:'إدارة الكاستنغ',reports:'البلاغات',revenue:'الإيرادات',audit:'سجل النشاط',appearance:'مظهر الموقع',banners:'إدارة البنرات',content:'إدارة المحتوى',features:'إدارة الخصائص',roles:'الأدوار والصلاحيات',widgets:'Widgets الداشبورد',system:'إعدادات النظام',storyboard:'Storyboard'};$('#dashboardTitle').textContent=labels[dashSection]||'Dashboard';$('#dashboardContent').innerHTML=u.role==='talent'?talentDash(u,dashSection):u.role==='company'?companyDash(u,dashSection):u.role==='photographer'?photographerDash(u,dashSection):adminDash(u,dashSection);wireDashboard(u)}renderNav();render();const unread=DB.state().notifications.filter(n=>n.userId===u.id&&!n.read).length;$('#notifCount').textContent=unread?unread:'';$('#notificationBtn').onclick=()=>showNotifications(u);}
function talentDash(u,s){const st=DB.state(),t=talentByUser(u.id,st),apps=st.applications.filter(a=>a.talentId===t?.id),self=st.selfTapes.filter(x=>x.talentId===t?.id);if(s==='overview')return `<div class="metrics">${metric('مشاهدات البروفايل','1,284','+18%')}${metric('طلبات التقديم',apps.length,'هذا الحساب')}${metric('Self‑Tapes',self.length,'طلبات نشطة')}${metric('Shortlists','7','+2 هذا الأسبوع')}</div><div class="grid-2">${panel('فرص مناسبة',`<div class="quick-list">${st.castings.slice(0,3).map(p=>`<div class="quick-item"><div><b>${p.title}</b><small>${p.city} • ${p.budget}</small></div><a class="btn primary sm" href="casting.html?id=${p.id}">عرض</a></div>`).join('')}</div>`)}${panel('قوة البروفايل',bars([['المعلومات',92],['Media',70],['Credits',65],['Verification',t?.verified?100:40]]))}</div>`;if(s==='profile')return panel('تعديل البروفايل',`<form id="talentProfileForm" class="form-grid"><label>الاسم<input id="pfName" value="${t?.name||''}"></label><label>المدينة<input id="pfCity" value="${t?.city||''}"></label><label>الفئة<select id="pfType">${['مودل','ممثل','UGC','كومبارس'].map(x=>`<option ${x===t?.type?'selected':''}>${x}</option>`).join('')}</select></label><label>العمر<input id="pfAge" type="number" value="${t?.age||18}"></label><label>Playing Age<input id="pfPlaying" value="${t?.playingAge||''}"></label><label>الطول cm<input id="pfHeight" type="number" value="${t?.height||0}"></label><label>السعر اليومي<input id="pfRate" type="number" value="${t?.dayRate||0}"></label><label>صورة URL<input id="pfImage" value="${t?.image||''}"></label><label class="full">نبذة<textarea id="pfBio" rows="4">${t?.bio||''}</textarea></label><label class="full">المهارات — افصل بفاصلة<input id="pfSkills" value="${(t?.skills||[]).join(', ')}"></label><div class="full"><button class="btn primary">حفظ البروفايل</button></div></form>`);if(s==='portfolio')return panel('محتواي',`<div class="panel-head"><div><b>Portfolio Feed</b><small class="muted"> كل منشوراتك تظهر أيضاً داخل بروفايلك</small></div><button class="btn primary sm" id="dashNewPost">+ نشر</button></div><div class="portfolio-grid dash-portfolio">${(st.posts||[]).filter(p=>p.talentId===t?.id).map(p=>`<div class="portfolio-tile dashboard-tile">${p.mediaType==='video'?`<img src="${p.coverUrl||t?.image||''}"><span class="portfolio-play">▶</span>`:`<img src="${p.mediaUrl||p.coverUrl||''}">`}<button data-delete-social="${p.id}">×</button></div>`).join('')||'<p class="muted">ما نشرت محتوى بعد.</p>'}</div><a class="btn secondary sm" href="feed.html">فتح صفحة التصفح</a>`);if(s==='opportunities')return panel('فرص مناسبة',`<div class="mini-grid">${st.castings.map(p=>`<div class="mini-card"><h4>${p.title}</h4><p>${p.city}<br>${p.budget}<br>Deadline ${p.deadline}</p><a class="btn primary sm" href="casting.html?id=${p.id}">التقديم</a></div>`).join('')}</div>`);if(s==='applications')return panel('طلباتي',`<div class="table-wrap"><table><thead><tr><th>المشروع</th><th>الدور</th><th>الحالة</th><th>التاريخ</th></tr></thead><tbody>${apps.map(a=>{const p=st.castings.find(x=>x.id===a.projectId),r=roleOf(p,a.roleId);return `<tr><td>${p?.title}</td><td>${r?.name}</td><td><span class="status ${statusClass(a.status)}">${statusLabel(a.status)}</span></td><td>${a.createdAt}</td></tr>`}).join('')||'<tr><td colspan="4">ما عندك تقديمات بعد.</td></tr>'}</tbody></table></div>`);if(s==='selftapes')return panel('Self‑Tape Requests',`<div class="quick-list">${self.map(x=>{const p=st.castings.find(p=>p.id===x.projectId);return `<div class="quick-item"><div><b>${p?.title}</b><small>${x.instructions}<br>Deadline: ${x.deadline}<br>Status: ${x.status}</small></div>${x.status==='requested'?`<button class="btn primary sm" data-submit-tape="${x.id}">رفع الرابط</button>`:`<span class="status green">Submitted</span>`}</div>`}).join('')||'<p>ماكو طلبات Self‑Tape حالياً.</p>'}</div>`);if(s==='messages')return messagesPanel(u,st);if(s==='analytics')return `<div class="metrics">${metric('مشاهدات 30 يوم','1,284','+18%')}${metric('ظهور بالبحث','4,620','+22%')}${metric('Shortlists','37','+8')}${metric('Conversion','3.1%','+0.4%')}</div>${panel('مصادر الزيارات',bars([['البحث',58],['Casting Calls',27],['روابط مباشرة',15]]))}`}

function photographerDash(u,s){const st=DB.state(),ph=DB.currentPhotographer?.(),projects=(st.photoProjects||[]).filter(p=>p.photographerId===ph?.id),tasks=st.photoTasks||[];
 if(s==='overview')return `<div class="metrics">${metric('المشاريع',projects.length,'مشاريعك')}${metric('المواهب المختارة',new Set(projects.flatMap(p=>p.talentIds||[])).size,'داخل المشاريع')}${metric('اللقطات',(st.shots||[]).filter(sh=>projects.some(p=>p.storyboardId===sh.storyboardId)).length,'Storyboard')}${metric('Tasks',tasks.filter(t=>projects.some(p=>p.id===t.projectId)&&t.status==='todo').length,'To Do')}</div><div class="grid-2">${panel('مشاريع حديثة',photoProjectCards(projects,st))}${panel('ابدأ بسرعة',`<div class="quick-list"><div class="quick-item"><div><b>مشروع جديد</b><small>اسم المشروع فقط بالبداية.</small></div><button class="btn primary sm" id="photoNewProject">+ New Project</button></div><div class="quick-item"><div><b>ابحث عن موهبة</b><small>استخدم نفس قاعدة المواهب الموجودة.</small></div><button class="btn secondary sm" data-photo-jump="search">فتح</button></div><div class="quick-item"><div><b>Storyboard</b><small>Frames + Shot Size + Description.</small></div><button class="btn secondary sm" data-photo-jump="storyboard">فتح</button></div></div>`)}</div>`;
 if(s==='projects')return panel('Projects',`<div class="panel-head"><p class="muted">مشروع بسيط أولاً. التفاصيل تنضاف فقط عند الحاجة.</p><button class="btn primary sm" id="photoNewProject">+ New Project</button></div>${photoProjectCards(projects,st)}`);
 if(s==='search'){const target=projects[0];return panel('Find Talents',`<div class="photo-search-head"><label>أضف إلى مشروع<select id="photoTargetProject">${projects.map(p=>`<option value="${p.id}">${p.name}</option>`).join('')}</select></label><input id="photoTalentSearch" placeholder="ابحث بالاسم أو المهارة..."></div><div class="photo-talent-grid" id="photoTalentGrid">${photoTalentCards(st.talents,target?.id,st)}</div>`)}
 if(s==='storyboard')return panel('Storyboard',projects.length?`<div class="photo-project-list">${projects.map(p=>{const sb=st.storyboards?.find(x=>x.projectId===p.id),count=(st.shots||[]).filter(x=>x.storyboardId===sb?.id).length;return `<a class="photo-project-row" href="storyboard.html?project=${p.id}"><div><b>${p.name}</b><small>${count} Shot${count===1?'':'s'}</small></div><span>فتح Storyboard ←</span></a>`}).join('')}</div>`:`<div class="empty-state"><h3>ما عندك مشروع بعد</h3><p>أنشئ مشروع وبعدها ابدأ أول Storyboard.</p><button class="btn primary" id="photoNewProject">+ New Project</button></div>`);
 if(s==='profile')return panel('Photographer Profile',`<form id="photographerProfileForm" class="form-grid"><label>الاسم<input id="photoPfName" value="${ph?.name||u.name}"></label><label>المدينة<input id="photoPfCity" value="${ph?.city||u.city||''}"></label><label class="full">نبذة<textarea id="photoPfBio" rows="4">${ph?.bio||''}</textarea></label><label class="full">التخصصات — افصل بفاصلة<input id="photoPfSpecs" value="${(ph?.specialties||[]).join(', ')}"></label><div class="full card-actions"><button class="btn primary">حفظ</button><a class="btn secondary" href="photographer.html?id=${ph?.id||'ph1'}">عرض البروفايل العام</a></div></form>`);
 if(s==='messages')return messagesPanel(u,st);
 return ''
}
function photoProjectCards(projects,st){return `<div class="photo-project-grid">${projects.map(p=>{const sb=st.storyboards?.find(x=>x.projectId===p.id),shots=(st.shots||[]).filter(x=>x.storyboardId===sb?.id).length,tasks=(st.photoTasks||[]).filter(x=>x.projectId===p.id&&x.status==='todo').length;return `<article class="photo-project-card"><div><h4>${p.name}</h4><p>${p.talentIds?.length||0} مواهب · ${shots} لقطات · ${tasks} Tasks</p></div><div class="card-actions"><a class="btn primary sm" href="photographer-project.html?id=${p.id}">فتح</a><a class="btn secondary sm" href="storyboard.html?project=${p.id}">Storyboard</a><button class="btn ghost sm" data-delete-photo-project="${p.id}">حذف</button></div></article>`}).join('')||'<div class="empty-state"><h3>ابدأ أول مشروع</h3><p>يكفي اسم المشروع بالبداية.</p></div>'}</div>`}
function photoTalentCards(talents,projectId,st){if(!projectId)return '<div class="empty-state"><p>أنشئ مشروع أولاً حتى تضيف مواهب.</p></div>';const p=st.photoProjects?.find(x=>x.id===projectId);return talents.map(t=>`<article class="photo-talent-card"><img src="${t.image||'image-placeholder.svg'}" alt="${t.name}"><div><b class="verified-name">${t.name}${t.verified?verifiedBadge('حساب موثق','compact'):''}</b><small>${t.type} · ${t.city}</small></div><div class="card-actions"><a class="btn secondary sm" href="talent.html?id=${t.id}">البروفايل</a><button class="btn ghost sm" data-photo-save-talent="${t.id}">${(st.photographers?.find(x=>x.userId===DB.currentUser()?.id)?.savedTalentIds||[]).includes(t.id)?'محفوظ':'حفظ'}</button><button class="btn primary sm" data-photo-add-talent="${t.id}" data-project="${projectId}" ${p?.talentIds?.includes(t.id)?'disabled':''}>${p?.talentIds?.includes(t.id)?'مضاف':'+ Add'}</button></div></article>`).join('')}
function companyDash(u,s){const st=DB.state(),c=companyByUser(u.id,st),projects=st.castings.filter(p=>p.companyId===c?.id),apps=st.applications.filter(a=>projects.some(p=>p.id===a.projectId)),shorts=st.shortlists.filter(x=>x.companyId===c?.id);if(s==='overview')return `<div class="metrics">${metric('المشاريع',projects.length,'نشطة')}${metric('المتقدمون',apps.length,'كل المشاريع')}${metric('Shortlists',shorts.length,'قوائم محفوظة')}${metric('Booked',apps.filter(a=>a.status==='booked').length,'حجز ناجح')}</div><div class="grid-2">${panel('المشاريع الحالية',`<div class="quick-list">${projects.map(p=>`<div class="quick-item"><div><b>${p.title}</b><small>${st.applications.filter(a=>a.projectId===p.id).length} متقدم • ${p.city}</small></div><button class="btn secondary sm" data-open-project="${p.id}">إدارة</button></div>`).join('')}</div>`,`<button class="btn primary sm" id="createProjectBtn">+ مشروع جديد</button>`)}${panel('Pipeline',bars([['To Review',55],['Selected',24],['Self‑Tape',12],['Booked',9]]))}</div>`;if(s==='projects')return panel('مشاريعي',`<div class="mini-grid">${projects.map(p=>`<div class="mini-card"><h4>${p.title}</h4><p>${p.city} • ${p.shootDate}<br>${p.budget}<br>${p.roles.length} دور</p><button class="btn secondary sm" data-open-project="${p.id}">إدارة</button></div>`).join('')}<div class="mini-card"><h4>+ مشروع جديد</h4><p>Breakdown + Role + Deadline.</p><button class="btn primary sm" id="createProjectBtn2">إنشاء</button></div></div>`);if(s==='submissions')return submissionsPanel(projects,st);if(s==='search')return panel('Talent Search',`<div class="filter-panel" style="grid-template-columns:1fr .5fr .5fr"><div class="filter-search">⌕ <input id="dashTalentSearch" placeholder="اسم أو مهارة"></div><select id="dashTalentCity"><option value="">كل المدن</option>${[...new Set(st.talents.map(t=>t.city))].map(x=>`<option>${x}</option>`).join('')}</select><select id="dashTalentType"><option value="">كل الفئات</option>${[...new Set(st.talents.map(t=>t.type))].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="mini-grid" id="dashTalentResults">${st.talents.map(t=>`<div class="mini-card"><h4 class="verified-name">${t.name}${t.verified?verifiedBadge('حساب موثق','compact'):''}</h4><p>${t.type} • ${t.city} • ${t.age}<br>${t.skills.join('، ')}</p><button class="btn primary sm" data-company-shortlist="${t.id}">+ Shortlist</button> <a class="btn secondary sm" href="talent.html?id=${t.id}">فتح</a></div>`).join('')}</div>`);if(s==='shortlists')return panel('Shortlists',`<div class="mini-grid">${shorts.map(sl=>`<div class="mini-card"><h4>${sl.name}</h4><p>${sl.talentIds.length} موهبة<br>${sl.notes||''}</p><a class="btn primary sm" href="shortlist.html?id=${sl.id}">مشاركة</a></div>`).join('')}<div class="mini-card"><h4>+ Shortlist جديدة</h4><p>أنشئ قائمة للمشروع والعميل.</p><button class="btn secondary sm" id="createShortlistBtn">إنشاء</button></div></div>`);if(s==='selftapes')return panel('Self‑Tapes',`<div class="table-wrap"><table><thead><tr><th>الموهبة</th><th>المشروع</th><th>Deadline</th><th>Status</th></tr></thead><tbody>${st.selfTapes.filter(x=>projects.some(p=>p.id===x.projectId)).map(x=>`<tr><td>${st.talents.find(t=>t.id===x.talentId)?.name}</td><td>${st.castings.find(p=>p.id===x.projectId)?.title}</td><td>${x.deadline}</td><td><span class="status ${x.status==='submitted'?'green':'blue'}">${x.status}</span></td></tr>`).join('')}</tbody></table></div>`);if(s==='schedule')return panel('Audition / Callback Schedule',`<div class="quick-list">${st.schedules.filter(x=>projects.some(p=>p.id===x.projectId)).map(sc=>`<div class="quick-item"><div><b>${sc.type.toUpperCase()} — ${sc.date}</b><small>${sc.location}<br>${sc.slots.map(x=>x.time+' '+(st.talents.find(t=>t.id===x.talentId)?.name||'')+' ('+x.status+')').join(' • ')}</small></div><button class="btn secondary sm" data-toast="تم فتح الجدول">فتح</button></div>`).join('')||'<p>ماكو جدول حالياً.</p>'}</div>`,`<button class="btn primary sm" data-toast="إضافة Schedule تحتاج Backend Live للإشعارات الخارجية">+ Schedule</button>`);if(s==='messages')return messagesPanel(u,st)}
function submissionsPanel(projects,st){const apps=st.applications.filter(a=>projects.some(p=>p.id===a.projectId));return panel('Applicant Manager',`<div class="pipeline-tabs"><button class="active" data-pipeline="all">الكل</button>${['to_review','selected','under_consideration','self_tape_requested','on_hold','booked','rejected'].map(x=>`<button data-pipeline="${x}">${statusLabel(x)}</button>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>الموهبة</th><th>المشروع / الدور</th><th>الحالة</th><th>إجراء</th></tr></thead><tbody id="submissionRows">${apps.map(a=>submissionRow(a,st)).join('')}</tbody></table></div>`)}function submissionRow(a,st){const t=st.talents.find(x=>x.id===a.talentId),p=st.castings.find(x=>x.id===a.projectId),r=roleOf(p,a.roleId);return `<tr data-app-status="${a.status}"><td><a href="talent.html?id=${t?.id}">${t?.name}</a></td><td>${p?.title}<br><span class="muted">${r?.name}</span></td><td><span class="status ${statusClass(a.status)}">${statusLabel(a.status)}</span></td><td><button class="btn secondary sm" data-app-action="${a.id}">إدارة</button></td></tr>`}
function messagesPanel(u,st){const cs=st.conversations.filter(c=>c.members.includes(u.id));return panel('الرسائل',`<div class="quick-list">${cs.map(c=>{const last=c.messages.at(-1);return `<div class="quick-item"><div><b>${st.castings.find(p=>p.id===c.projectId)?.title||'Conversation'}</b><small>${last?.text||''}</small></div><button class="btn secondary sm" data-conversation="${c.id}">فتح</button></div>`}).join('')||'<p>ماكو محادثات بعد.</p>'}</div>`)}
function adminDash(u,s){const st=DB.state();if(s==='overview')return `<div class="metrics">${metric('المستخدمون',st.users.length,'Demo DB')}${metric('المواهب',st.talents.length,'Profiles')}${metric('الشركات',st.companies.length,'Companies')}${metric('Casting Calls',st.castings.length,'Projects')}</div><div class="grid-2">${panel('آخر المستخدمين',`<div class="table-wrap"><table><thead><tr><th>الاسم</th><th>النوع</th><th>المدينة</th><th>الحالة</th></tr></thead><tbody>${st.users.slice(-8).map(x=>`<tr><td>${x.name}</td><td>${x.role}</td><td>${x.city}</td><td><span class="status ${x.verified?'green':'yellow'}">${x.verified?'موثق':'جديد'}</span></td></tr>`).join('')}</tbody></table></div>`)}${panel('يحتاج إجراء',`<div class="quick-list"><div class="quick-item"><div><b>${st.verifications.filter(v=>v.status==='pending').length} توثيق</b><small>بانتظار المراجعة</small></div></div><div class="quick-item"><div><b>${st.reports.filter(r=>r.status==='open').length} بلاغ</b><small>مفتوح</small></div></div></div>`)}</div>`;if(s==='users')return panel('المستخدمون',`<div class="table-wrap"><table><thead><tr><th>الاسم</th><th>الإيميل</th><th>النوع</th><th>موثق</th><th>إجراء</th></tr></thead><tbody>${st.users.map(x=>`<tr><td>${x.name}</td><td>${x.email}</td><td>${x.role}</td><td>${x.verified?verifiedBadge('حساب موثق','compact'):'—'}</td><td><button class="btn secondary sm" data-toast="فتح الحساب">فتح</button> <button class="btn danger sm" data-toast="تم إيقاف الحساب تجريبياً">إيقاف</button></td></tr>`).join('')}</tbody></table></div>`);if(s==='verification')return panel('طلبات التوثيق',`<div class="mini-grid">${st.verifications.map(v=>{const x=st.users.find(u=>u.id===v.userId);return `<div class="mini-card"><h4>${x?.name||v.userId}</h4><p>${v.type} • ${v.status}<br>${v.createdAt}</p><button class="btn primary sm" data-toast="تمت الموافقة التجريبية">Approve</button> <button class="btn danger sm" data-toast="تم الرفض التجريبي">Reject</button></div>`}).join('')}</div>`);if(s==='castings')return panel('إدارة Casting Calls',`<div class="table-wrap"><table><thead><tr><th>المشروع</th><th>الشركة</th><th>الحالة</th><th>Deadline</th></tr></thead><tbody>${st.castings.map(p=>`<tr><td>${p.title}</td><td>${companyById(p.companyId,st)?.name}</td><td><span class="status green">${p.status}</span></td><td>${p.deadline}</td></tr>`).join('')}</tbody></table></div>`);if(s==='reports')return panel('البلاغات',`<div class="quick-list">${st.reports.map(r=>`<div class="quick-item"><div><b>${r.targetType} — ${r.targetId}</b><small>${r.reason} • ${r.status}</small></div><button class="btn secondary sm" data-toast="تمت مراجعة البلاغ">مراجعة</button></div>`).join('')}</div>`);if(s==='revenue')return `<div class="metrics">${metric('هذا الشهر','18.4M د.ع','Demo')}${metric('B2B','8.2M','44%')}${metric('Premium','4.7M','26%')}${metric('Boost/Fees','5.5M','30%')}</div>${panel('مصادر الإيراد',bars([['اشتراكات الشركات',44],['Premium',26],['Boost',18],['عمولات',12]]))}`;if(s==='audit')return panel('Audit Log',`<div class="table-wrap"><table><thead><tr><th>Action</th><th>Resource</th><th>Admin</th><th>Time</th></tr></thead><tbody>${st.audit.map(x=>`<tr><td>${x.action}</td><td>${x.at}</td></tr>`).join('')}</tbody></table></div>`)}
function wireDashboard(u){$$('[data-toast]').forEach(b=>b.onclick=()=>toast(b.dataset.toast));$('#createProjectBtn')?.addEventListener('click',showCreateProject);$('#createProjectBtn2')?.addEventListener('click',showCreateProject);$('#createShortlistBtn')?.addEventListener('click',()=>{const n=prompt('اسم الـShortlist');if(!n)return;const st=DB.state(),c=companyByUser(u.id,st),p=st.castings.find(x=>x.companyId===c?.id);DB.createShortlist(c.id,p?.id||'',n);toast('تم إنشاء Shortlist');dashSection='shortlists';$('#dashboardNav [data-dash="shortlists"]')?.click()});$$('[data-company-shortlist]').forEach(b=>b.onclick=()=>{const st=DB.state(),c=companyByUser(u.id,st);let sl=st.shortlists.find(x=>x.companyId===c?.id);if(!sl)sl=DB.createShortlist(c.id,st.castings[0]?.id,'Quick Shortlist');DB.addShortlistItem(sl.id,b.dataset.companyShortlist);toast('تمت الإضافة')});$$('[data-pipeline]').forEach(b=>b.onclick=()=>{$$('[data-pipeline]').forEach(x=>x.classList.remove('active'));b.classList.add('active');$$('#submissionRows tr').forEach(r=>r.style.display=b.dataset.pipeline==='all'||r.dataset.appStatus===b.dataset.pipeline?'':'none')});$$('[data-app-action]').forEach(b=>b.onclick=()=>showApplicationManager(b.dataset.appAction));$$('[data-submit-tape]').forEach(b=>b.onclick=()=>{const url=prompt('الصق رابط فيديو الـSelf‑Tape');if(url){DB.submitSelfTape(b.dataset.submitTape,url);toast('تم إرسال الـSelf‑Tape');location.reload()}});$$('[data-conversation]').forEach(b=>b.onclick=()=>showConversation(b.dataset.conversation,u));$('#talentProfileForm')?.addEventListener('submit',e=>{e.preventDefault();const st=DB.state(),t=talentByUser(u.id,st);Object.assign(t,{name:$('#pfName').value,city:$('#pfCity').value,type:$('#pfType').value,age:+$('#pfAge').value,playingAge:$('#pfPlaying').value,height:+$('#pfHeight').value,dayRate:+$('#pfRate').value,image:$('#pfImage').value,bio:$('#pfBio').value,skills:$('#pfSkills').value.split(',').map(x=>x.trim()).filter(Boolean)});DB.save(st);DB.updateUser(u.id,{name:t.name,city:t.city,bio:t.bio});toast('تم حفظ البروفايل')});$$('[data-open-project]').forEach(b=>b.onclick=()=>toast('إدارة المشروع موجودة عبر المتقدمين وSelf‑Tapes والجدولة'));$('#dashNewPost')?.addEventListener('click',createPostModal);$$('[data-delete-social]').forEach(b=>b.onclick=()=>{if(confirm('حذف المنشور؟')&&DB.deletePost(b.dataset.deleteSocial)){toast('تم الحذف');b.closest('.dashboard-tile')?.remove()}})}
function showCreateProject(){showModal(`<h3>مشروع Casting جديد</h3><form id="createProjectForm" class="form-grid"><label class="full">اسم المشروع<input id="cpTitle" required></label><label>المدينة<input id="cpCity" value="بغداد"></label><label>النوع<select id="cpCat"><option>Commercial</option><option>Beauty</option><option>UGC</option><option>Extras</option></select></label><label>تاريخ التصوير<input id="cpShoot" type="date" required></label><label>Deadline<input id="cpDeadline" type="date" required></label><label>اسم الدور<input id="cpRole" value="الدور الرئيسي"></label><label>فئة الموهبة<select id="cpType"><option>ممثل</option><option>مودل</option><option>UGC</option><option>كومبارس</option></select></label><label>العمر من<input id="cpMin" type="number" value="20"></label><label>العمر إلى<input id="cpMax" type="number" value="35"></label><label>الأجر<input id="cpPay" type="number" value="400000"></label><label>Budget display<input id="cpBudget" value="400,000 د.ع"></label><label class="full">الوصف<textarea id="cpDesc" rows="3" required></textarea></label><label class="full">المتطلبات<input id="cpReq" placeholder="خبرة، مهارة، توفر..."></label><div class="full"><button class="btn primary">نشر Casting Call</button></div></form>`);$('#createProjectForm').onsubmit=e=>{e.preventDefault();const u=DB.currentUser(),c=companyByUser(u.id,DB.state());DB.createCasting(c.id,{title:$('#cpTitle').value,city:$('#cpCity').value,category:$('#cpCat').value,shootDate:$('#cpShoot').value,deadline:$('#cpDeadline').value,roleName:$('#cpRole').value,type:$('#cpType').value,ageMin:$('#cpMin').value,ageMax:$('#cpMax').value,pay:$('#cpPay').value,budget:$('#cpBudget').value,description:$('#cpDesc').value,requirements:$('#cpReq').value});closeModal();toast('تم نشر المشروع');location.reload()}}
function showApplicationManager(id){const st=DB.state(),a=st.applications.find(x=>x.id===id),t=st.talents.find(x=>x.id===a?.talentId),p=st.castings.find(x=>x.id===a?.projectId),r=roleOf(p,a?.roleId);showModal(`<h3>${t?.name}</h3><p>${p?.title} — ${r?.name}</p><p>${a?.message||''}</p><div class="facts"><div class="fact"><span>الحالة</span><b>${statusLabel(a.status)}</b></div><div class="fact"><span>العمر</span><b>${t?.age}</b></div><div class="fact"><span>المدينة</span><b>${t?.city}</b></div><div class="fact"><span>الأجر</span><b>${money(t?.dayRate)}</b></div></div><h3>تغيير الحالة</h3><div class="pipeline-tabs">${['selected','under_consideration','on_avail','on_hold','backup','booked','rejected'].map(x=>`<button data-set-status="${x}">${statusLabel(x)}</button>`).join('')}</div><button class="btn primary" id="requestTapeBtn">طلب Self‑Tape</button>`);$$('[data-set-status]').forEach(b=>b.onclick=()=>{DB.setApplicationStatus(id,b.dataset.setStatus);toast('تم تحديث الحالة');closeModal();location.reload()});$('#requestTapeBtn').onclick=()=>{const ins=prompt('تعليمات الـSelf‑Tape','Medium shot + Intro + 2 takes');const dl=prompt('Deadline','2026-08-28T20:00');if(ins&&dl){DB.requestSelfTape(id,ins,dl);toast('تم إرسال Self‑Tape Request');closeModal();location.reload()}}}
function showConversation(id,u){const st=DB.state(),c=st.conversations.find(x=>x.id===id);showModal(`<h3>المحادثة</h3><div class="quick-list" id="conversationMessages">${c.messages.map(m=>`<div class="quick-item"><div><b>${m.senderId===u.id?'أنت':'الطرف الآخر'}</b><small>${m.text}<br>${m.at}</small></div></div>`).join('')}</div><form id="messageForm" class="form-stack" style="margin-top:12px"><label>رسالة<input id="messageText" required></label><button class="btn primary">إرسال</button></form>`);$('#messageForm').onsubmit=e=>{e.preventDefault();DB.sendMessage(id,u.id,$('#messageText').value);toast('تم الإرسال');closeModal();showConversation(id,u)}}
function showNotifications(u){const st=DB.state(),ns=st.notifications.filter(n=>n.userId===u.id);showModal(`<h3>الإشعارات</h3><div class="quick-list">${ns.map(n=>`<div class="quick-item"><div><b>${n.title}</b><small>${n.body}<br>${n.at}</small></div></div>`).join('')||'<p>ماكو إشعارات.</p>'}</div>`);ns.forEach(n=>n.read=true);DB.save(st);$('#notifCount').textContent=''}
function showModal(html){$('#modalContent').innerHTML=html;$('#appModal').classList.add('show');$$('[data-close-modal]').forEach(b=>b.onclick=closeModal)}function closeModal(){$('#appModal')?.classList.remove('show')}
function settingsPage(){const u=DB.currentUser();if(!u)return location.href='auth.html#login';const cities=['بغداد','أربيل','البصرة','النجف','كربلاء','السليمانية','الموصل'];$('#settingsCity').innerHTML=cities.map(x=>`<option ${x===u.city?'selected':''}>${x}</option>`).join('');$('#settingsName').value=u.name;$('#settingsEmail').value=u.email;$('#settingsPhone').value=u.phone||'';$('#settingsBio').value=u.bio||'';$('#phoneVisible').checked=!!u.phoneVisible;$('#castingNotif').checked=u.castingNotif!==false;$('#emailNotif').checked=u.emailNotif!==false;$('#settingsForm').onsubmit=e=>{e.preventDefault();DB.updateUser(u.id,{name:$('#settingsName').value,email:$('#settingsEmail').value,city:$('#settingsCity').value,phone:$('#settingsPhone').value,bio:$('#settingsBio').value,phoneVisible:$('#phoneVisible').checked,castingNotif:$('#castingNotif').checked,emailNotif:$('#emailNotif').checked});toast('تم حفظ الإعدادات')};$('#changePassword').onclick=()=>{const p=prompt('كلمة المرور الجديدة — 6 أحرف أو أكثر');if(p?.length>=6){DB.updateUser(u.id,{password:p});toast('تم تغيير كلمة المرور')}};$('#deleteAccount').onclick=()=>{if(['u-admin','u-company','u-talent'].includes(u.id))return toast('الحساب التجريبي الأساسي ما ينحذف');if(confirm('متأكد؟')){const st=DB.state();st.users=st.users.filter(x=>x.id!==u.id);DB.save(st);DB.logout();location.href='index.html'}};bindGlobal()}
function shortlistPage(){const st=DB.state(),sl=st.shortlists.find(x=>x.id===(qs('id')||'s1'));if(!sl){$('#shortlistTitle').textContent='Shortlist غير موجودة';return}const p=st.castings.find(x=>x.id===sl.projectId);$('#shortlistTitle').textContent=sl.name;$('#shortlistSubtitle').textContent=(p?.title||'')+' • '+sl.talentIds.length+' مواهب';$('#shortlistGrid').innerHTML=sl.talentIds.map(id=>st.talents.find(t=>t.id===id)).filter(Boolean).map(cardTalent).join('');$('#copyShortlistLink').onclick=()=>{navigator.clipboard?.writeText(location.href);toast('تم نسخ الرابط')};bindGlobal()}


function companyPage(){const st=DB.state(),c=st.companies.find(x=>x.id===(qs('id')||'c1'));if(!c){location.href='castings.html';return}const projects=st.castings.filter(p=>p.companyId===c.id);$('#companyHeader').innerHTML=`<div class="profile-header company-profile-header"><div class="company-logo-lg">${(c.name||'C').trim().charAt(0)}</div><div class="profile-title"><div class="eyebrow profile-verified-line">${c.verified?`${verifiedBadge('شركة موثقة','profile')}<span>جهة موثقة</span>`:'Company Profile'}</div><h1 class="verified-name profile-name">${c.name}${c.verified?verifiedBadge('شركة موثقة','profile'):''}</h1><p>${c.type||''} • ${c.city||''}</p></div><div class="profile-header-actions"><a class="btn primary" href="castings.html">فرص الشركة</a><button class="btn secondary" id="companyContact">طلب تواصل</button></div></div>`;$('#companyAbout').innerHTML=`<h3>عن الجهة</h3><p>${c.bio||'لا توجد نبذة مضافة بعد.'}</p><div class="company-trust-grid"><div><b>${projects.length}</b><span>مشاريع منشورة</span></div><div><b>${projects.filter(p=>p.status==='open').length}</b><span>فرص مفتوحة</span></div><div><b class="verification-stat">${c.verified?verifiedBadge('شركة موثقة','profile'):'جديد'}</b><span>حالة الحساب</span></div></div>`;$('#companyCastings').innerHTML=`<div class="panel-head"><h3>أحدث فرص الكاستنغ</h3><a class="link-pill" href="castings.html">كل الفرص</a></div><div class="casting-list">${projects.map(cardCasting).join('')||'<p class="muted">ماكو مشاريع منشورة حالياً.</p>'}</div>`;$('#companyFacts').innerHTML=`<h3>معلومات الجهة</h3><div class="facts"><div class="fact"><span>المدينة</span><b>${c.city||'-'}</b></div><div class="fact"><span>النوع</span><b>${c.type||'-'}</b></div><div class="fact"><span>التوثيق</span><b class="verification-stat">${c.verified?verifiedBadge('شركة موثقة','compact'):'غير موثقة'}</b></div><div class="fact"><span>المنصة</span><b>Cast Iraq</b></div></div>`;$('#companyActions').innerHTML=`<h3>التواصل</h3><p>للحفاظ على خصوصية الطرفين، بيانات التواصل المباشر تظهر بعد تسجيل الدخول.</p><a class="btn primary full" href="auth.html#login">تسجيل الدخول للتواصل</a>`;$('#companyContact')?.addEventListener('click',()=>{if(!DB.currentUser())return location.href='auth.html#login';toast('تم إرسال طلب تواصل تجريبي')});bindGlobal()}

function relativeTime(v){const d=new Date(v),n=new Date(),m=Math.max(0,Math.floor((n-d)/60000));if(m<1)return 'الآن';if(m<60)return `قبل ${m} د`;const h=Math.floor(m/60);if(h<24)return `قبل ${h} س`;const days=Math.floor(h/24);return days<7?`قبل ${days} يوم`:d.toLocaleDateString('ar-IQ')}
function socialMedia(p){if(p.mediaType==='video'){const u=p.mediaUrl||'';if(/youtube\.com|youtu\.be/.test(u)){let id='';try{const x=new URL(u);id=x.hostname.includes('youtu.be')?x.pathname.slice(1):(x.searchParams.get('v')||'')}catch{}return id?`<div class="post-media video-media"><iframe src="https://www.youtube.com/embed/${id}" title="video" allowfullscreen loading="lazy"></iframe></div>`:''}return `<div class="post-media video-media"><video controls preload="metadata" poster="${p.coverUrl||''}"><source src="${u}">متصفحك لا يدعم الفيديو.</video><span class="video-badge">▶ VIDEO</span></div>`}return `<div class="post-media"><img src="${p.mediaUrl||p.coverUrl||''}" alt="${p.caption||'Talent post'}" loading="lazy"></div>`}

function socialIcon(name,active=false){const a=active?' fill="currentColor"':'';const common='width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"';if(name==='heart')return `<svg ${common}${a}><path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.6l-1-1a5.5 5.5 0 0 0-7.8 7.8l1 1L12 21l7.8-7.6 1-1a5.5 5.5 0 0 0 0-7.8Z"/></svg>`;if(name==='comment')return `<svg ${common}><path d="M21 15a4 4 0 0 1-4 4H8l-5 3 1.6-4.8A8 8 0 1 1 21 15Z"/></svg>`;if(name==='share')return `<svg ${common}><path d="M12 16V4"/><path d="m7 9 5-5 5 5"/><path d="M5 13v6a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1v-6"/></svg>`;return `<svg ${common}${a}><path d="M6 3h12a1 1 0 0 1 1 1v17l-7-4-7 4V4a1 1 0 0 1 1-1Z"/></svg>`}
function feedPostCard(p,s=DB.state()){const t=s.talents.find(x=>x.id===p.talentId)||{},u=DB.currentUser(),liked=!!u&&(p.likedBy||[]).includes(u.id),saved=!!u&&(p.savedBy||[]).includes(u.id),work=p.kind==='work'&&(p.projectTitle||p.brand);return `<article class="social-post" data-post="${p.id}"><div class="post-head"><a class="post-author" href="talent.html?id=${t.id}"><img src="${t.image||''}" alt="${t.name||''}"><div><b class="verified-name">${t.name||'موهبة'}${t.verified?verifiedBadge('حساب موثق','compact'):''}</b><span>${t.type||''} • ${t.city||''} • ${relativeTime(p.createdAt)}</span></div></a><button class="post-more" data-post-menu="${p.id}">•••</button></div>${work?`<div class="work-credit"><span>WORK CREDIT</span><div><b>${p.projectTitle||'عمل سابق'}</b>${p.brand?`<small>${p.brand}</small>`:''}${p.creditRole?`<small>${p.creditRole}</small>`:''}</div></div>`:''}${socialMedia(p)}<div class="post-actions"><div class="post-actions-primary"><button class="social-action ${liked?'active':''}" data-like-post="${p.id}" aria-label="إعجاب">${socialIcon('heart',liked)}</button><button class="social-action" data-focus-comment="${p.id}" aria-label="تعليق">${socialIcon('comment')}</button><button class="social-action" data-share-post="${p.id}" aria-label="مشاركة">${socialIcon('share')}</button></div><button class="social-action ${saved?'active':''}" data-save-post="${p.id}" aria-label="حفظ">${socialIcon('bookmark',saved)}</button></div><div class="post-copy"><b>${Number(p.likes||0).toLocaleString('en-US')} إعجاب</b><p><a href="talent.html?id=${t.id}"><strong>${t.name||''}</strong></a> ${p.caption||''}</p>${(p.tags||[]).length?`<div class="post-tags">${p.tags.map(x=>`<span>#${x}</span>`).join('')}</div>`:''}${(p.comments||[]).length?`<div class="comments-preview">${p.comments.slice(-2).map(c=>`<p><b>${c.name}</b> ${c.text}</p>`).join('')}</div>`:''}<form class="comment-form" data-comment-form="${p.id}"><input id="comment-${p.id}" placeholder="أضف تعليقاً..." maxlength="500"><button>نشر</button></form></div></article>`}
function createPostModal(){const u=DB.currentUser();if(!u)return location.href='auth.html#login';if(u.role!=='talent')return toast('النشر متاح لحسابات المواهب فقط');showModal(`<div class="create-post-head"><span class="eyebrow">NEW PORTFOLIO POST</span><h3>نشر صورة، فيديو أو عمل سابق</h3><p class="muted">كل منشور يظهر بصفحة التصفح وينضاف تلقائياً إلى بروفايلك.</p></div><form id="socialPostForm" class="form-grid"><label>نوع المنشور<select id="spKind"><option value="photo">صورة</option><option value="video">فيديو</option><option value="work">عمل سابق / Credit</option></select></label><label>نوع الميديا<select id="spMediaType"><option value="photo">صورة</option><option value="video">فيديو</option></select></label><label class="full">رابط الصورة / الفيديو<input id="spMedia" type="url" placeholder="https://..." required></label><label class="full image-upload-row">أو اختر صورة من جهازك<input id="spImageFile" type="file" accept="image/jpeg,image/png,image/webp"><small>للنسخة التجريبية: الصور فقط وبحجم أقل من 1.2MB. الفيديو يرفع كرابط لحين ربط Supabase Storage.</small></label><label class="full">الوصف<textarea id="spCaption" rows="3" maxlength="1000" placeholder="احچي عن اللقطة أو الشغل..."></textarea></label><label>اسم المشروع<input id="spProject" placeholder="مثال: Ramadan Campaign"></label><label>البراند / العميل<input id="spBrand" placeholder="اسم البراند"></label><label>دورك بالعمل<input id="spRole" placeholder="Model / Actor / UGC"></label><label>Tags<input id="spTags" placeholder="Beauty, Commercial"></label><label class="full">Cover للفيديو (اختياري)<input id="spCover" type="url" placeholder="رابط صورة الغلاف"></label><div class="full create-post-submit"><button class="btn primary">نشر الآن</button></div></form>`);const file=$('#spImageFile'),url=$('#spMedia');file.onchange=()=>{const f=file.files?.[0];if(!f)return;if(f.size>1200000){file.value='';return toast('الصورة أكبر من 1.2MB')}const r=new FileReader();r.onload=()=>url.value=r.result;r.readAsDataURL(f)};$('#spKind').onchange=()=>{if($('#spKind').value==='video')$('#spMediaType').value='video';if($('#spKind').value==='photo')$('#spMediaType').value='photo'};$('#socialPostForm').onsubmit=e=>{e.preventDefault();try{DB.createPost({kind:$('#spKind').value,mediaType:$('#spMediaType').value,mediaUrl:$('#spMedia').value,coverUrl:$('#spCover').value,caption:$('#spCaption').value,projectTitle:$('#spProject').value,brand:$('#spBrand').value,creditRole:$('#spRole').value,tags:$('#spTags').value.split(',').map(x=>x.trim()).filter(Boolean)});closeModal();toast('تم نشر العمل');if(page==='feed')feedPage();else location.reload()}catch(err){toast('تعذر نشر المحتوى')}}}
function bindSocialActions(render){$$('[data-like-post]').forEach(b=>b.onclick=()=>{try{DB.toggleLike(b.dataset.likePost);render()}catch{return location.href='auth.html#login'}});$$('[data-save-post]').forEach(b=>b.onclick=()=>{try{DB.toggleSave(b.dataset.savePost);render()}catch{return location.href='auth.html#login'}});$$('[data-focus-comment]').forEach(b=>b.onclick=()=>$('#comment-'+b.dataset.focusComment)?.focus());$$('[data-share-post]').forEach(b=>b.onclick=async()=>{const url=location.href.split('#')[0]+'#post-'+b.dataset.sharePost;try{if(navigator.share)await navigator.share({title:'Cast Iraq',url});else{await navigator.clipboard.writeText(url);toast('تم نسخ رابط المنشور')}}catch{}});$$('[data-comment-form]').forEach(f=>f.onsubmit=e=>{e.preventDefault();const input=$('#comment-'+f.dataset.commentForm),v=input?.value?.trim();if(!v)return;try{DB.addComment(f.dataset.commentForm,v);render()}catch{return location.href='auth.html#login'}});$$('[data-post-menu]').forEach(b=>b.onclick=()=>{const st=DB.state(),p=st.posts.find(x=>x.id===b.dataset.postMenu),u=DB.currentUser(),t=st.talents.find(x=>x.id===p?.talentId);if(u?.role==='talent'&&t?.userId===u.id){if(confirm('حذف هذا المنشور؟')&&DB.deletePost(p.id)){toast('تم حذف المنشور');render()}}else toast('خيارات المنشور')})}
function feedPage(){const filterHolder={value:document.querySelector('[data-feed-filter].active')?.dataset.feedFilter||'all'};function render(){const s=DB.state(),u=DB.currentUser(),q=($('#feedSearch')?.value||'').trim().toLowerCase(),filter=document.querySelector('[data-feed-filter].active')?.dataset.feedFilter||filterHolder.value;let list=[...(s.posts||[])].sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));list=list.filter(p=>{const t=s.talents.find(x=>x.id===p.talentId)||{};const hay=[t.name,t.type,t.city,p.caption,p.projectTitle,p.brand,p.creditRole,...(p.tags||[])].join(' ').toLowerCase();return(!q||hay.includes(q))&&(filter==='all'||(filter==='video'?p.mediaType==='video':filter==='photo'?p.mediaType==='photo'&&p.kind!=='work':p.kind==='work'))});$('#feedList').innerHTML=list.map(p=>feedPostCard(p,s)).join('')||'<div class="feed-empty">ماكو محتوى مطابق حالياً.</div>';bindSocialActions(render);$('#feedComposer').innerHTML=u?.role==='talent'?`<div class="quick-composer"><img src="${talentByUser(u.id,s)?.image||''}" alt=""><button id="quickCreatePost">شارك صورة، فيديو أو عمل جديد...</button><span>▧</span><span>▶</span></div>`:'';$('#quickCreatePost')?.addEventListener('click',createPostModal)}
 const s=DB.state();$('#feedTalentStrip').innerHTML=s.talents.slice(0,8).map(t=>`<a class="talent-bubble" href="talent.html?id=${t.id}"><span><img src="${t.image||''}" alt="${t.name}"></span><b>${t.name.split(' ')[0]}</b></a>`).join('');$('#feedSuggestions').innerHTML=s.talents.slice(0,5).map(t=>`<a class="suggestion-row" href="talent.html?id=${t.id}"><img src="${t.image||''}" alt=""><div><b class="verified-name">${t.name}${t.verified?verifiedBadge('حساب موثق','compact'):''}</b><span>${t.type} • ${t.city}</span></div><em>عرض</em></a>`).join('');$('#feedCastings').innerHTML=s.castings.filter(x=>x.status==='open').slice(0,3).map(p=>`<a class="mini-casting" href="casting.html?id=${p.id}"><b>${p.title}</b><span>${p.city} • ${p.deadline}</span></a>`).join('');$$('[data-feed-filter]').forEach(b=>b.onclick=()=>{$$('[data-feed-filter]').forEach(x=>x.classList.remove('active'));b.classList.add('active');render()});$('#feedSearch')?.addEventListener('input',render);['#newPostTop','#mobileNewPost'].forEach(x=>$(x)?.addEventListener('click',createPostModal));render();bindGlobal()}
function renderTalentPortfolio(){const box=$('#profilePortfolio');if(!box)return;const st=DB.state(),t=st.talents.find(x=>x.id===(qs('id')||'t1'));if(!t)return;const posts=(st.posts||[]).filter(p=>p.talentId===t.id).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));box.innerHTML=`<div class="profile-section-head"><div><h3>Portfolio Feed</h3><p>${posts.length} منشور • صور، فيديو وأعمال سابقة</p></div><a class="btn ghost sm" href="feed.html">فتح التصفح</a></div><div class="portfolio-grid">${posts.map(p=>`<a class="portfolio-tile" href="feed.html#${p.id}">${p.mediaType==='video'?`<img src="${p.coverUrl||t.image}" alt=""><span class="portfolio-play">▶</span>`:`<img src="${p.mediaUrl||p.coverUrl}" alt="">`}${p.kind==='work'?'<span class="portfolio-work">WORK</span>':''}</a>`).join('')||'<div class="muted">ماكو منشورات بعد.</div>'}</div>`}


// ===== V5 product layer =====
function ensureSiteSettings(){const st=DB.state();if(!st.siteSettings){st.siteSettings={siteName:'Cast Iraq',heroImage:'',companyImage:'',announcement:'',banners:[],updatedAt:new Date().toISOString()};DB.save(st)}return st.siteSettings}
function uiIcon(name){const icons={home:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 10.5 12 3l9 7.5"/><path d="M5.5 9.8V21h13V9.8"/></svg>',search:'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="6.5"/><path d="m16 16 4.5 4.5"/></svg>',plus:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 5v14M5 12h14"/></svg>',opportunities:'<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3.5" y="7" width="17" height="12" rx="2"/><path d="M9 7V5.5h6V7M3.5 11.5h17"/></svg>',account:'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="8" r="3.5"/><path d="M5 20c.8-4 3.1-6 7-6s6.2 2 7 6"/></svg>'};return icons[name]||''}
function addMobileShell(){if(['auth','settings'].includes(page))return;if(page!=='dashboard'&&!document.querySelector('.mobile-app-bar')){const u=DB.currentUser();const bar=document.createElement('div');bar.className='mobile-app-bar';bar.innerHTML=`<div class="app-wordmark">Cast Iraq</div><div class="app-actions"><a class="app-icon" href="castings.html" aria-label="الفرص">${uiIcon('opportunities')}</a><a class="app-icon" href="${u?'dashboard.html':'auth.html#login'}" aria-label="الحساب">${uiIcon('account')}</a></div>`;document.body.prepend(bar)}if(!document.querySelector('.app-bottom-nav')){const nav=document.createElement('nav');nav.className='app-bottom-nav';const active=pageNavKey();const u=DB.currentUser();let centerAction;if(u?.role==='company'){centerAction=`<a class="create-main nav-primary-action" href="dashboard.html?create=1" aria-label="إنشاء Casting">${uiIcon('plus')}<span>إنشاء</span></a>`}else if(u?.role==='talent'){centerAction=`<button class="create-main nav-primary-action" id="appCreatePost" aria-label="نشر">${uiIcon('plus')}<span>نشر</span></button>`}else if(u?.role==='photographer'){centerAction=`<a class="create-main nav-primary-action" href="dashboard.html?newProject=1" aria-label="مشروع جديد">${uiIcon('plus')}<span>مشروع</span></a>`}else if(u?.role==='admin'){centerAction=`<a class="create-main nav-primary-action" href="dashboard.html" aria-label="لوحة الإدارة">${uiIcon('plus')}<span>إدارة</span></a>`}else{centerAction=`<a class="create-main nav-primary-action" href="auth.html#signup" aria-label="إنشاء حساب">${uiIcon('plus')}<span>انضم</span></a>`}nav.innerHTML=`<a class="${active==='feed'?'active':''}" href="feed.html">${uiIcon('home')}<span>الرئيسية</span></a><a class="${active==='explore'?'active':''}" href="explore.html">${uiIcon('search')}<span>بحث</span></a>${centerAction}<a class="${active==='castings'?'active':''}" href="castings.html">${uiIcon('opportunities')}<span>فرص</span></a><a class="${page==='talent'||page==='dashboard'?'active':''}" href="${u?'dashboard.html':'auth.html#login'}">${uiIcon('account')}<span>حسابي</span></a>`;document.body.appendChild(nav);$('#appCreatePost')?.addEventListener('click',createPostModal)}if(page==='explore'&&!document.querySelector('.mobile-filter-toggle')){const fp=$('.filter-panel');if(fp){const b=document.createElement('button');b.className='mobile-filter-toggle';b.type='button';b.textContent='☷';b.setAttribute('aria-label','الفلاتر');fp.appendChild(b);b.onclick=()=>fp.classList.toggle('mobile-expanded')}}}
function renderManagedBanners(){if(page!=='home')return;const st=DB.state(),cfg=ensureSiteSettings(),slides=(cfg.banners||[]).filter(x=>x.enabled!==false);document.querySelector('.managed-banner')?.remove();if(!slides.length)return;const sec=document.createElement('section');sec.className='managed-banner';sec.innerHTML=`<div class="managed-banner-track">${slides.map((b,i)=>`<a class="managed-slide ${i===0?'active':''}" href="${b.link||'#'}"><img src="${b.image||'image-placeholder.svg'}" alt="${b.title||'Banner'}"><span class="managed-slide-overlay"></span><div class="managed-slide-copy"><h2>${b.title||''}</h2><p>${b.subtitle||''}</p><span class="btn primary sm">اكتشف أكثر</span></div></a>`).join('')}<div class="managed-dots">${slides.map((_,i)=>`<button class="${i===0?'active':''}" data-banner-dot="${i}"></button>`).join('')}</div></div>`;const hero=document.querySelector('.hero');hero?.after(sec);let idx=0;const show=n=>{const els=[...sec.querySelectorAll('.managed-slide')],dots=[...sec.querySelectorAll('[data-banner-dot]')];idx=(n+els.length)%els.length;els.forEach((x,i)=>x.classList.toggle('active',i===idx));dots.forEach((x,i)=>x.classList.toggle('active',i===idx))};sec.querySelectorAll('[data-banner-dot]').forEach(b=>b.onclick=e=>{e.preventDefault();show(+b.dataset.bannerDot)});if(slides.length>1)setInterval(()=>show(idx+1),5000);const hi=document.querySelector('.hero-photo img'),ci=document.querySelector('.company-visual img');if(hi&&cfg.heroImage)hi.src=cfg.heroImage;if(ci&&cfg.companyImage)ci.src=cfg.companyImage}
function safeUserDelete(userId){const st=DB.state();const u=st.users.find(x=>x.id===userId);if(!u||u.role==='admin')return false;const talent=st.talents.find(t=>t.userId===userId),company=st.companies.find(c=>c.userId===userId);if(talent){const tid=talent.id;st.posts=(st.posts||[]).filter(p=>p.talentId!==tid);st.applications=(st.applications||[]).filter(a=>a.talentId!==tid);st.selfTapes=(st.selfTapes||[]).filter(x=>x.talentId!==tid);(st.shortlists||[]).forEach(sl=>sl.talentIds=sl.talentIds.filter(id=>id!==tid));st.talents=st.talents.filter(t=>t.id!==tid)}if(company){const ids=st.castings.filter(p=>p.companyId===company.id).map(p=>p.id);st.applications=st.applications.filter(a=>!ids.includes(a.projectId));st.selfTapes=st.selfTapes.filter(x=>!ids.includes(x.projectId));st.shortlists=st.shortlists.filter(x=>x.companyId!==company.id);st.castings=st.castings.filter(p=>p.companyId!==company.id);st.companies=st.companies.filter(c=>c.id!==company.id)}st.notifications=(st.notifications||[]).filter(n=>n.userId!==userId);st.conversations=(st.conversations||[]).filter(c=>!c.members.includes(userId));st.verifications=(st.verifications||[]).filter(v=>v.userId!==userId);st.users=st.users.filter(x=>x.id!==userId);st.moderationLog=st.moderationLog||[];st.moderationLog.unshift({action:'delete_user',userId,at:new Date().toISOString()});DB.save(st);return true}
function setUserSuspended(userId,value){const st=DB.state(),u=st.users.find(x=>x.id===userId);if(!u||u.role==='admin')return false;u.suspended=!!value;st.moderationLog=st.moderationLog||[];st.moderationLog.unshift({action:value?'suspend_user':'activate_user',userId,at:new Date().toISOString()});DB.save(st);return true}
function adminAppearance(){const st=DB.state(),cfg=ensureSiteSettings();return panel('مظهر الموقع',`<div class="admin-section-intro"><div><h3>الهوية والصور الرئيسية</h3><p>غيّر الصور بدون تعديل الكود. التغييرات تنحفظ مباشرة داخل نسخة الديمو.</p></div></div><form id="appearanceForm" class="form-grid"><label class="full">اسم المنصة<input id="siteNameField" value="${cfg.siteName||'Cast Iraq'}"></label><label class="full">صورة Hero الرئيسية<input id="heroImageField" value="${cfg.heroImage||''}" placeholder="https://..."></label><div class="full admin-media-preview"><img src="${cfg.heroImage||'image-placeholder.svg'}" alt="Hero preview"></div><label class="full">صورة قسم الشركات<input id="companyImageField" value="${cfg.companyImage||''}" placeholder="https://..."></label><div class="full admin-media-preview"><img src="${cfg.companyImage||'image-placeholder.svg'}" alt="Company preview"></div><label class="full">إعلان قصير / Announcement<input id="announcementField" value="${cfg.announcement||''}" placeholder="مثال: التسجيل مفتوح لحملة رمضان"></label><div class="full"><button class="btn primary">حفظ المظهر</button></div></form>`)}
function adminBanners(){const cfg=ensureSiteSettings(),rows=(cfg.banners||[]);return panel('البنرات المتحركة',`<div class="admin-section-intro"><div><h3>Slider الواجهة</h3><p>فعّل، عطّل، أضف أو احذف البنرات. تتبدل تلقائياً كل 5 ثواني.</p></div><button class="btn primary sm" id="addBannerBtn">+ بنر جديد</button></div><div class="banner-admin-list">${rows.map(b=>`<div class="banner-admin-row"><img src="${b.image||'image-placeholder.svg'}" alt=""><div><b>${b.title||'بدون عنوان'}</b><small>${b.subtitle||''}</small><small>${b.enabled===false?'معطل':'فعال'} • ${b.link||'#'}</small></div><div class="action-cluster"><button class="btn secondary sm" data-edit-banner="${b.id}">تعديل</button><button class="btn ghost sm" data-toggle-banner="${b.id}">${b.enabled===false?'تفعيل':'تعطيل'}</button><button class="btn danger sm" data-delete-banner="${b.id}">حذف</button></div></div>`).join('')||'<p class="muted">ماكو بنرات حالياً.</p>'}</div>`)}
function adminContent(){const st=DB.state();return `<div class="dashboard-kpis"><div class="kpi-mini"><b>${st.posts.length}</b><span>منشورات</span></div><div class="kpi-mini"><b>${st.posts.filter(p=>p.mediaType==='video').length}</b><span>فيديو</span></div><div class="kpi-mini"><b>${st.castings.length}</b><span>Casting Calls</span></div><div class="kpi-mini"><b>${st.talents.length}</b><span>بروفايلات</span></div><div class="kpi-mini"><b>${st.reports.filter(r=>r.status==='open').length}</b><span>بلاغات مفتوحة</span></div></div>${panel('إدارة منشورات الـFeed',`<div class="table-wrap"><table><thead><tr><th>الموهبة</th><th>النوع</th><th>الوصف</th><th>Likes</th><th>إجراء</th></tr></thead><tbody>${st.posts.map(p=>{const t=st.talents.find(x=>x.id===p.talentId);return `<tr><td>${t?.name||'-'}</td><td>${p.mediaType}</td><td>${(p.caption||'').slice(0,55)}</td><td>${p.likes||0}</td><td><button class="btn secondary sm" data-feature-post="${p.id}">${p.featured?'إلغاء التثبيت':'تثبيت'}</button> <button class="btn danger sm" data-admin-delete-post="${p.id}">حذف</button></td></tr>`}).join('')}</tbody></table></div>`)}`}
function adminSystem(){const st=DB.state();let size=0;try{size=new Blob([localStorage.getItem('castiraq_release_v2')||'']).size}catch{}return `<div class="admin-grid"><div class="admin-tool-card"><h4>قاعدة بيانات الديمو</h4><p>حجم التخزين المحلي الحالي.</p><b>${(size/1024).toFixed(1)} KB</b></div><div class="admin-tool-card"><h4>Build</h4><p>نسخة الواجهة الحالية.</p><b>V5 Mobile Pro</b></div><div class="admin-tool-card"><h4>نسخة احتياطية</h4><p>صدّر JSON لكل بيانات الديمو.</p><button class="btn secondary sm" id="exportDbBtn">تصدير</button></div><div class="admin-tool-card danger-zone"><h4>Reset Demo</h4><p>يرجع كل البيانات الافتراضية ويحذف التغييرات.</p><button class="btn danger sm" id="resetDemoBtn">إعادة ضبط</button></div></div>`}
// Override admin dashboard with operational controls.
function adminDash(u,s){const st=DB.state();if(s==='appearance')return adminAppearance();if(s==='banners')return adminBanners();if(s==='content')return adminContent();if(s==='features')return adminFeatures();if(s==='roles')return adminRoles();if(s==='widgets')return adminWidgets();if(s==='system')return adminSystem();if(s==='overview')return `<div class="dashboard-kpis"><div class="kpi-mini"><b>${st.users.length}</b><span>مستخدم</span></div><div class="kpi-mini"><b>${st.talents.length}</b><span>موهبة</span></div><div class="kpi-mini"><b>${st.companies.length}</b><span>شركة</span></div><div class="kpi-mini"><b>${st.posts.length}</b><span>منشور</span></div><div class="kpi-mini"><b>${st.castings.filter(p=>p.status==='open').length}</b><span>فرصة نشطة</span></div></div><div class="grid-2">${panel('إدارة سريعة',`<div class="quick-list"><div class="quick-item"><div><b>مظهر الموقع</b><small>Hero + صور + Announcement</small></div><button class="btn secondary sm" data-jump-admin="appearance">فتح</button></div><div class="quick-item"><div><b>البنرات المتحركة</b><small>${(st.siteSettings?.banners||[]).length} بنر</small></div><button class="btn secondary sm" data-jump-admin="banners">إدارة</button></div><div class="quick-item"><div><b>المحتوى</b><small>${st.posts.length} منشور</small></div><button class="btn secondary sm" data-jump-admin="content">مراجعة</button></div></div>`)}${panel('يحتاج إجراء',`<div class="quick-list"><div class="quick-item"><div><b>${st.verifications.filter(v=>v.status==='pending').length} توثيق</b><small>بانتظار المراجعة</small></div></div><div class="quick-item"><div><b>${st.reports.filter(r=>r.status==='open').length} بلاغ</b><small>مفتوح</small></div></div><div class="quick-item"><div><b>${st.users.filter(x=>x.suspended).length} حساب موقوف</b><small>يمكن إعادة تفعيله</small></div></div></div>`)}</div>`;if(s==='users')return panel('إدارة المستخدمين',`<div class="admin-section-intro"><div><h3>الحسابات</h3><p>فتح، إيقاف، إعادة تفعيل أو حذف الحساب مع بياناته المرتبطة.</p></div></div><div class="table-wrap"><table><thead><tr><th>الاسم</th><th>الإيميل</th><th>النوع</th><th>الحالة</th><th>إجراء</th></tr></thead><tbody>${st.users.map(x=>`<tr><td>${x.name}</td><td>${x.email}</td><td><select class="role-select" data-user-role="${x.id}">${Object.values(st.rbac?.roles||{}).filter(r=>r.enabled!==false).map(r=>`<option value="${r.id}" ${r.id===(x.roleId|| (x.role==='admin'?'super_admin':x.role==='company'?'company_manager':x.role==='photographer'?'photographer':'talent'))?'selected':''}>${r.name}</option>`).join('')}</select></td><td><span class="status ${x.suspended?'red':x.verified?'green':'yellow'}">${x.suspended?'موقوف':x.verified?'موثق':'نشط'}</span></td><td>${x.role==='admin'?'<span class="muted">محمي</span>':`<button class="btn secondary sm" data-toggle-user="${x.id}">${x.suspended?'تفعيل':'إيقاف'}</button> <button class="btn danger sm" data-delete-user="${x.id}">حذف</button>`}</td></tr>`).join('')}</tbody></table></div>`);if(s==='verification')return panel('طلبات التوثيق',`<div class="mini-grid">${st.verifications.map(v=>{const x=st.users.find(u=>u.id===v.userId);return `<div class="mini-card"><h4>${x?.name||v.userId}</h4><p>${v.type} • ${v.status}<br>${v.createdAt}</p><button class="btn primary sm" data-approve-verification="${v.userId}">Approve</button> <button class="btn danger sm" data-reject-verification="${v.userId}">Reject</button></div>`}).join('')}</div>`);if(s==='castings')return panel('إدارة Casting Calls',`<div class="table-wrap"><table><thead><tr><th>المشروع</th><th>الشركة</th><th>الحالة</th><th>Deadline</th><th>إجراء</th></tr></thead><tbody>${st.castings.map(p=>`<tr><td>${p.title}</td><td>${companyById(p.companyId,st)?.name}</td><td><span class="status ${p.status==='open'?'green':'yellow'}">${p.status}</span></td><td>${p.deadline}</td><td><button class="btn secondary sm" data-toggle-casting="${p.id}">${p.status==='open'?'إغلاق':'فتح'}</button> <button class="btn danger sm" data-delete-casting="${p.id}">حذف</button></td></tr>`).join('')}</tbody></table></div>`);if(s==='reports')return panel('البلاغات',`<div class="quick-list">${st.reports.map(r=>`<div class="quick-item"><div><b>${r.targetType} — ${r.targetId}</b><small>${r.reason} • ${r.status}</small></div><button class="btn secondary sm" data-close-report="${r.id}">إغلاق البلاغ</button></div>`).join('')}</div>`);if(s==='revenue')return `<div class="metrics">${metric('هذا الشهر','18.4M د.ع','Demo')}${metric('B2B','8.2M','44%')}${metric('Premium','4.7M','26%')}${metric('Boost/Fees','5.5M','30%')}</div>${panel('مصادر الإيراد',bars([['اشتراكات الشركات',44],['Premium',26],['Boost',18],['عمولات',12]]))}`;if(s==='audit')return panel('Audit Log',`<div class="table-wrap"><table><thead><tr><th>Action</th><th>Resource</th><th>Admin</th><th>Time</th></tr></thead><tbody>${[...(st.auditLogs||[]),...(st.moderationLog||[]),...(st.audit||[])].slice(0,100).map(x=>`<tr><td>${x.action}</td><td>${x.resource||'—'}</td><td>${x.actor||'—'}</td><td>${x.at}</td></tr>`).join('')}</tbody></table></div>`)}
// Extend dashboard wiring while preserving original capabilities.
const _wireDashboardBase=wireDashboard;wireDashboard=function(u){_wireDashboardBase(u);$$('[data-jump-admin]').forEach(b=>b.onclick=()=>{$(`#dashboardNav [data-dash="${b.dataset.jumpAdmin}"]`)?.click()});$('#appearanceForm')?.addEventListener('submit',e=>{e.preventDefault();const st=DB.state();st.siteSettings=st.siteSettings||{};Object.assign(st.siteSettings,{siteName:$('#siteNameField').value,heroImage:$('#heroImageField').value,companyImage:$('#companyImageField').value,announcement:$('#announcementField').value,updatedAt:new Date().toISOString()});DB.save(st);toast('تم حفظ مظهر الموقع')});$('#addBannerBtn')?.addEventListener('click',()=>editBanner());$$('[data-edit-banner]').forEach(b=>b.onclick=()=>editBanner(b.dataset.editBanner));$$('[data-toggle-banner]').forEach(b=>b.onclick=()=>{const st=DB.state(),x=st.siteSettings.banners.find(z=>z.id===b.dataset.toggleBanner);if(x)x.enabled=x.enabled===false;DB.save(st);toast('تم تحديث البنر');location.reload()});$$('[data-delete-banner]').forEach(b=>b.onclick=()=>{if(!confirm('حذف هذا البنر؟'))return;const st=DB.state();st.siteSettings.banners=st.siteSettings.banners.filter(x=>x.id!==b.dataset.deleteBanner);DB.save(st);location.reload()});$$('[data-toggle-user]').forEach(b=>b.onclick=()=>{const st=DB.state(),x=st.users.find(z=>z.id===b.dataset.toggleUser);setUserSuspended(x.id,!x.suspended);toast(x.suspended?'تم إيقاف الحساب':'تم تفعيل الحساب');location.reload()});$$('[data-delete-user]').forEach(b=>b.onclick=()=>{const st=DB.state(),x=st.users.find(z=>z.id===b.dataset.deleteUser);if(confirm(`حذف حساب ${x?.name} وكل بياناته المرتبطة؟`)&&safeUserDelete(b.dataset.deleteUser)){toast('تم حذف الحساب');location.reload()}});$$('[data-admin-delete-post]').forEach(b=>b.onclick=()=>{if(!confirm('حذف هذا المنشور من المنصة؟'))return;const st=DB.state();st.posts=st.posts.filter(p=>p.id!==b.dataset.adminDeletePost);DB.save(st);location.reload()});$$('[data-feature-post]').forEach(b=>b.onclick=()=>{const st=DB.state(),p=st.posts.find(x=>x.id===b.dataset.featurePost);p.featured=!p.featured;DB.save(st);toast('تم تحديث التثبيت');location.reload()});$$('[data-toggle-casting]').forEach(b=>b.onclick=()=>{const st=DB.state(),p=st.castings.find(x=>x.id===b.dataset.toggleCasting);p.status=p.status==='open'?'closed':'open';DB.save(st);location.reload()});$$('[data-delete-casting]').forEach(b=>b.onclick=()=>{if(!confirm('حذف المشروع والتقديمات المرتبطة؟'))return;const st=DB.state(),id=b.dataset.deleteCasting;st.castings=st.castings.filter(x=>x.id!==id);st.applications=st.applications.filter(x=>x.projectId!==id);st.selfTapes=st.selfTapes.filter(x=>x.projectId!==id);DB.save(st);location.reload()});$$('[data-approve-verification]').forEach(b=>b.onclick=()=>{const st=DB.state(),u2=st.users.find(x=>x.id===b.dataset.approveVerification);if(u2)u2.verified=true;const t=st.talents.find(x=>x.userId===u2?.id),c=st.companies.find(x=>x.userId===u2?.id);if(t)t.verified=true;if(c)c.verified=true;st.verifications.filter(v=>v.userId===u2?.id).forEach(v=>v.status='approved');DB.save(st);location.reload()});$$('[data-reject-verification]').forEach(b=>b.onclick=()=>{const st=DB.state();st.verifications.filter(v=>v.userId===b.dataset.rejectVerification).forEach(v=>v.status='rejected');DB.save(st);location.reload()});$$('[data-close-report]').forEach(b=>b.onclick=()=>{const st=DB.state(),r=st.reports.find(x=>x.id===b.dataset.closeReport);if(r)r.status='closed';DB.save(st);location.reload()});$('#exportDbBtn')?.addEventListener('click',()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(DB.state(),null,2)],{type:'application/json'}));a.download='castiraq-demo-backup.json';a.click();URL.revokeObjectURL(a.href)});$('#resetDemoBtn')?.addEventListener('click',()=>{if(confirm('ترجع كل بيانات الديمو للوضع الأصلي؟')){DB.reset();location.href='auth.html#login'}})}
function editBanner(id){const st=DB.state(),cfg=ensureSiteSettings(),x=(cfg.banners||[]).find(b=>b.id===id)||{id:'bn-'+Date.now(),title:'',subtitle:'',image:'',link:'explore.html',enabled:true};showModal(`<h3>${id?'تعديل البنر':'بنر جديد'}</h3><form id="bannerForm" class="form-grid"><label class="full">العنوان<input id="bnTitle" value="${x.title||''}" required></label><label class="full">النص<input id="bnSubtitle" value="${x.subtitle||''}"></label><label class="full">رابط الصورة<input id="bnImage" value="${x.image||''}" required></label><label class="full">الرابط عند الضغط<input id="bnLink" value="${x.link||'explore.html'}"></label><label class="full">الحالة<select id="bnEnabled"><option value="true" ${x.enabled!==false?'selected':''}>فعال</option><option value="false" ${x.enabled===false?'selected':''}>معطل</option></select></label><div class="full"><button class="btn primary">حفظ البنر</button></div></form>`);$('#bannerForm').onsubmit=e=>{e.preventDefault();const st2=DB.state();st2.siteSettings=st2.siteSettings||{banners:[]};st2.siteSettings.banners=st2.siteSettings.banners||[];const item={id:x.id,title:$('#bnTitle').value,subtitle:$('#bnSubtitle').value,image:$('#bnImage').value,link:$('#bnLink').value,enabled:$('#bnEnabled').value==='true'};const i=st2.siteSettings.banners.findIndex(b=>b.id===x.id);if(i>=0)st2.siteSettings.banners[i]=item;else st2.siteSettings.banners.push(item);DB.save(st2);closeModal();toast('تم حفظ البنر');location.reload()}}
// Instagram-inspired talent header and grid.
const _talentPageBase=talentPage;talentPage=function(){_talentPageBase();addMobileShell();const st=DB.state(),t=st.talents.find(x=>x.id===(qs('id')||'t1'));if(!t)return;const h=$('#profileHeader .profile-title');const c=$('#profileContact');if(c){c.textContent='متابعة';c.classList.add('profile-follow-btn');c.onclick=()=>toast('تمت المتابعة تجريبياً')}}
renderTalentPortfolio=function(){const box=$('#profilePortfolio');if(!box)return;const st=DB.state(),t=st.talents.find(x=>x.id===(qs('id')||'t1'));if(!t)return;const posts=(st.posts||[]).filter(p=>p.talentId===t.id).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));box.innerHTML=`<div class="profile-tabs"><button class="active" data-profile-tab="all">▦ المنشورات</button><button data-profile-tab="video">▶ الفيديو</button><button data-profile-tab="work">★ الأعمال</button></div><div class="portfolio-grid ig-grid" id="igPortfolioGrid"></div>`;function draw(f='all'){const list=posts.filter(p=>f==='all'||(f==='video'?p.mediaType==='video':p.kind==='work'));$('#igPortfolioGrid').innerHTML=list.map(p=>`<a class="portfolio-tile" href="feed.html#${p.id}"><img src="${p.mediaType==='video'?(p.coverUrl||t.image):(p.mediaUrl||p.coverUrl)}" alt="">${p.mediaType==='video'?'<span class="portfolio-play">▶</span>':''}${p.kind==='work'?'<span class="portfolio-work">WORK</span>':''}</a>`).join('')||'<div class="muted" style="padding:16px;grid-column:1/-1">ماكو محتوى بهذا القسم.</div>'}$$('[data-profile-tab]',box).forEach(b=>b.onclick=()=>{$$('[data-profile-tab]',box).forEach(x=>x.classList.remove('active'));b.classList.add('active');draw(b.dataset.profileTab)});draw()}
